function build_market_deck(): array {
    $deck = [];
    $market_cards = [
        'doorkicker' => 6,
        'driver' => 6,
        'sentinel' => 4,
        'mechanic' => 3,
        'scuba' => 3,
        'hacker' => 3,
        'saboteur' => 3,
        'jack' => 1,
        'chameleon' => 1,
        'racoon' => 1,
        'offshore' => 8,
        'orbital' => 5,
        'burn' => 5,
        'paperwork' => 3,
        'burglary' => 3,
        'paradrop' => 5,
        'multitasking' => 2,
        'training' => 3,
        'reinforcements' => 3,
        'swordcane' => 4,
        'bazooka' => 2,
        'ram' => 4,
        'holoprojector' => 2,
        'drone' => 4,
        'hackingdeck' => 2,
        'grapplinghook' => 2,
        'passports' => 4,
        'motorbike' => 4,
        'limousine' => 3,
        'helicopter' => 2,
    ];
    foreach ($market_cards as $id => $count) {
        for ($i = 0; $i < $count; $i++) {
            $deck[] = $id;
        }
    }
    shuffle($deck);
    return $deck;
}

function build_mission_decks(): array {
    $missions = [
        1 => [
            'slap' => 0,
            'getaway' => 5,
            'wrestling' => 5,
            'convent' => 5,
            'gate' => 5,
        ],
        2 => [
            'hijinx' => 3,
            'duel' => 3,
            'troupe' => 3,
            'retinal' => 3,
        ],
        3 => [
            'cargo' => 2,
            'rooftop' => 2,
            'megastar' => 2,
            'embassy' => 2,
        ],
    ];
    $decks = [];
    foreach ($missions as $tier => $cards) {
        $deck = [];
        foreach ($cards as $id => $count) {
            for ($i = 0; $i < $count; $i++) {
                $deck[] = $id;
            }
        }
        shuffle($deck);
        $decks[$tier] = $deck;
    }
    return $decks;
}

function get_starter_deck(): array {
    $deck = [];
    for ($i = 0; $i < 6; $i++) $deck[] = 'money_1';
    $deck[] = 'muscle';
    $deck[] = 'muscle';
    $deck[] = 'shadow';
    $deck[] = 'red_tape';
    shuffle($deck);
    return $deck;
}
